from __future__ import annotations

import base64
import hashlib
import json
import re
import shutil
import sys
import zlib
from pathlib import Path

from core.private_home import PrivateHome

repo = Path("/Users/steventran/jobpipe")
sys.path.insert(0, str(repo))
sources = [
    (
        Path("/Users/steventran/Downloads/Resume_Steven_Tran_Software_Engineer_2026-09.pdf"),
        "software-engineer.pdf",
        "software_engineer",
    ),
    (
        Path("/Users/steventran/Downloads/Resume_Steven_Tran_Full_Stack_Software_Engineer_2026-09.pdf"),
        "full-stack-software-engineer.pdf",
        "full_stack_engineer",
    ),
]
for source, _, _ in sources:
    if not source.is_file():
        raise SystemExit(f"resume source missing: {source.name}")

def pdf_strings(path: Path) -> list[str]:
    data = path.read_bytes()
    values = []
    for match in re.finditer(rb"stream\r?\n(.*?)endstream", data, re.S):
        raw = match.group(1).strip()
        decoded = None
        try:
            decoded = zlib.decompress(base64.a85decode(raw, adobe=True))
        except Exception:
            try:
                decoded = zlib.decompress(raw)
            except Exception:
                continue
        text = decoded.decode("latin1", "ignore")
        for value in re.findall(r"\((.*?)\)\s*Tj", text, re.S):
            value = re.sub(
                r"\\([0-7]{1,3})",
                lambda m: chr(int(m.group(1), 8)),
                value,
            )
            value = value.replace("\\(", "(").replace("\\)", ")").replace("\\\\", "\\")
            values.append(value)
    return values

text_values = pdf_strings(sources[0][0])
flat = "\n".join(text_values)
name = next((v.strip() for v in text_values if v.strip()), "")
name_parts = name.split()
if len(name_parts) < 2:
    raise SystemExit("could not verify candidate name from resume")

raw_pdf = sources[0][0].read_bytes().decode("latin1", "ignore")
email_match = re.search(r"mailto:([^\)\s]+)", raw_pdf, re.I)
if not email_match:
    email_match = re.search(r"[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}", flat, re.I)
if not email_match:
    raise SystemExit("could not verify email from resume")
email = email_match.group(1) if email_match.lastindex else email_match.group(0)

phone_match = re.search(r"\(\d{3}\)\s*\d{3}-\d{4}", flat)
location_match = re.search(r"Los Angeles,\s*CA", flat, re.I)
github_match = re.search(r"(?:www\.)?github\.com/[A-Za-z0-9_.-]+", flat, re.I)
portfolio_match = re.search(r"(?:www\.)?[A-Za-z0-9.-]+\.(?:com|dev|io)", flat, re.I)

home = PrivateHome.discover()
paths = home.ensure()
variants = []
for source, target_name, role_family in sources:
    target = paths.master_documents / target_name
    shutil.copy2(source, target)
    target.chmod(0o600)
    digest = hashlib.sha256(target.read_bytes()).hexdigest()
    variants.append(
        {
            "file_path": str(target),
            "artifact_id": digest,
            "role_family": role_family,
        }
    )

personal = {
    "first_name": name_parts[0],
    "last_name": " ".join(name_parts[1:]),
    "email": email.strip(),
}
if phone_match:
    personal["phone"] = phone_match.group(0)
if location_match:
    personal["location"] = location_match.group(0)
if github_match:
    personal["github"] = "https://" + github_match.group(0).removeprefix("www.")
if portfolio_match:
    candidate = portfolio_match.group(0)
    if "github.com" not in candidate.casefold():
        personal["portfolio"] = "https://" + candidate.removeprefix("www.")

facts = {
    "schema_version": 1,
    "normalized": {
        "personal": personal,
        "default_resume": variants[0]["file_path"],
        "resume_variants": variants,
        "preferences": {
            "roles": [
                "Software Engineer",
                "Backend Engineer",
                "Full Stack Engineer",
                "Platform Engineer",
                "Java Engineer",
            ],
            "locations": ["Los Angeles, CA", "Remote, US"],
            "remote_only": False,
        },
        "workday": {
            "auto_login": True,
            "auto_register": True,
        },
    },
}
answers = {
    "schema_version": 1,
    "answers": {},
}
policy = {
    "schema_version": 1,
    "autonomy": {
        "mode": "LOW_RISK_AUTOPILOT",
        "email_verification_agent_enabled": False,
        "allow_keychain_login": True,
        "allow_account_registration": True,
    },
    "mailbox": {
        "enabled": False,
        "provider": "imap",
        "host": "",
        "port": 993,
        "mailbox": "INBOX",
        "keychain_service": "com.jobops.mailbox.imap",
    },
}

home.write_text(paths.profile_facts, json.dumps(facts, indent=2, sort_keys=True) + "\n")
home.write_text(paths.verified_answers, json.dumps(answers, indent=2, sort_keys=True) + "\n")
home.write_text(paths.policy, json.dumps(policy, indent=2, sort_keys=True) + "\n")

print(json.dumps({
    "profile_initialized": True,
    "resume_variants": len(variants),
    "verified_answers": 0,
    "policy_mode": "LOW_RISK_AUTOPILOT",
}, sort_keys=True))
